<?php
namespace App\Http\Controllers\Tenant;
use App\Http\Controllers\Controller;use App\Models\Event;use App\Models\EventCheckin;use App\Models\Ticket;use App\Tenancy\TenantContext;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CheckinController extends Controller{
 public function index(TenantContext $ctx,Event $event){$tenant=$ctx->requireTenant();abort_unless($event->tenant_id===$tenant->id,404);$checkins=EventCheckin::where('event_id',$event->id)->latest('checked_in_at')->paginate(100);return view('tenant.manage.checkin.index',compact('event','checkins'));}
 public function manual(Request $r,TenantContext $ctx,Event $event){$tenant=$ctx->requireTenant();abort_unless($event->tenant_id===$tenant->id,404);$d=$r->validate(['user_id'=>'nullable|integer|exists:users,id','guest_count'=>'required|integer|min:1|max:20']);EventCheckin::create(['event_id'=>$event->id,'user_id'=>$d['user_id']??null,'checked_in_by'=>$r->user()->id,'method'=>'manual','guest_count'=>$d['guest_count'],'checked_in_at'=>now()]);return back()->with('status','Guest checked in.');}
 public function ticket(Request $r,TenantContext $ctx,Event $event){$tenant=$ctx->requireTenant();abort_unless($event->tenant_id===$tenant->id,404);$d=$r->validate(['qr_token'=>'required|string|max:100']);DB::transaction(function()use($d,$event,$r){$ticket=Ticket::where('qr_token',$d['qr_token'])->lockForUpdate()->firstOrFail();$ticket->load('orderItem.order');abort_unless(optional(optional($ticket->orderItem)->order)->event_id===$event->id,422,'Ticket is for another event.');abort_if($ticket->status!=='valid'||$ticket->checked_in_at,422,'Ticket is not valid for check-in.');$ticket->update(['checked_in_at'=>now(),'status'=>'used']);EventCheckin::create(['event_id'=>$event->id,'user_id'=>$ticket->user_id,'ticket_id'=>$ticket->id,'checked_in_by'=>$r->user()->id,'method'=>'qr','guest_count'=>1,'checked_in_at'=>now()]);});return back()->with('status','Ticket accepted.');}
}